// Six separated impact circles: aim the constellation, not its empty center.
const SHARED_COMET_SIGNATURE=['六芒の星雨',28,7,'照準地点を中心に距離100の六角形で6か所を予告し、0.9秒後に各地点の半径40へ240%。通常範囲では中央は空白。範囲補正は各着弾円だけを拡大し、重なった円はそれぞれ命中する。壁の向こうには落ちず、壁越しの敵には当たらない。自分が中心から500を超える・壁に隠れる・死亡・地域移動で解除。属性抽選で配置は変わらない。','M26 4V19M18 10L26 19L34 10M26 19L9 40M26 19V44M26 19L43 40M4 40H14M21 44H31M38 40H48'];
SIGNATURE_SKILLS.push(SHARED_COMET_SIGNATURE);Object.assign(GEM.crafted_5_4,{name:SHARED_COMET_SIGNATURE[0],cost:28,cool:7,desc:SHARED_COMET_SIGNATURE[3],ability:null,signature:100,tags:['spell','area']});
SIGNATURE_AUDIO.push(['sharedcomet',520,.4]);SKILL_AUDIO_FAMILIES.metal.add('sharedcomet');
function sharedCometValid(s){return s.owner===p&&s.world===dungeon&&!s.finished&&!dead&&p?.hp>0&&dist(p,s)<=500&&lineClear(p,s);}
function sharedCometPoints(s){return Array.from({length:6},(_,i)=>({x:s.x+100*Math.cos(i*Math.PI/3),y:s.y+100*Math.sin(i*Math.PI/3)}));}
function sharedCometTargets(s,point){return enemies.filter(e=>e.hp>0&&dist(e,point)<=40*s.build.radius+1e-8&&lineClear(point,e));}
const sharedCometCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{let result=sharedCometCastBase(build,...args);if(GEM[build.type]?.signature!==100)return result;let s=signatureSpells.at(-1);if(s?.mode!==100)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==100||v===s);s.owner=p;s.world=dungeon;s.finished=false;s.target=null;return result;};
const sharedCometStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==100)return sharedCometStepBase(s,dt);if(!sharedCometValid(s)){s.finished=true;return false;}if(paused||!Number.isFinite(dt)||dt<=0)return true;s.time+=dt;if(s.time+1e-8<.9)return true;s.finished=true;const impacts=sharedCometPoints(s).filter(point=>lineClear(s,point)).map(point=>({point,targets:sharedCometTargets(s,point)}));for(const {point,targets} of impacts){for(const e of targets)if(e.hp>0&&enemies.includes(e))spellHit(e,s.damage*2.4,s.build);burst(point.x,point.y,40*s.build.radius,ELEMENTS[s.build.elements[0]].color);}playSignatureAudio(100,true,s.x,s.y);return false;};
const sharedCometPaintBase=paintSignatureSpells;paintSignatureSpells=()=>{sharedCometPaintBase();for(const s of signatureSpells){if(s.mode!==100||!sharedCometValid(s)||!visibleAt(s.x,s.y))continue;const color=ELEMENTS[s.build.elements[0]].color;for(const point of sharedCometPoints(s)){if(!lineClear(s,point))continue;groundRing(point.x,point.y,40*s.build.radius,color,2);groundRing(point.x,point.y,Math.max(3,40*s.build.radius*(1-s.time/.9)),'#f5e8bc',2);paintLinkLine(s,point,color,1);}}};
const sharedCometStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===100?{label:'六芒 · 6点着弾',value:Math.min(1,s.time/.9),waiting:true}:sharedCometStatusBase(s);
